  # base case 
  if n <= 1: 
    return n 
  # recursive case 
  else:
    return(fibonacci(n-1) + fibonacci(n-2))

### Instruction:
Develop an algorithm to find the smallest element in a given array of integers using recursion.

### Response:
public static int getSmallestElementRecursive(int[] arr, int start, int end) {
    if (start == end) {
        return arr[start];
    }

    int min = getSmallestElementRecursive(arr, start+1, end);

    if (arr[start] < min) {
        return arr[start];
    } else {
        return min;
    }
}
